<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import DefaultLayout from '@/layouts/DefaultLayout.vue';import BaseButton from '@/components/ui/BaseButton.vue';import{useApi}from'@/composables/useApi';import type{ApiResponse,Certificate}from'@/types';const route=useRoute(),router=useRouter(),api=useApi(),code=ref(String(route.params.code||'')),certificate=ref<(Certificate&{isValid?:boolean})|null>(null),error=ref('');async function verify(){if(!code.value.trim())return;error.value='';try{const r=await api.get<ApiResponse<Certificate&{isValid?:boolean}>>(`/certificates/verify/${encodeURIComponent(code.value.trim())}`);certificate.value=r.data||null;if(route.params.code!==code.value)router.replace(`/certificates/verify/${encodeURIComponent(code.value)}`)}catch(e){certificate.value=null;error.value=e instanceof Error?e.message:'Không tìm thấy chứng chỉ'}}onMounted(()=>{if(code.value)verify()})</script>
<template><DefaultLayout><main class="mx-auto max-w-2xl px-4 py-14"><h1 class="text-center text-3xl font-extrabold">Xác minh chứng chỉ</h1><form class="my-7 flex gap-2" @submit.prevent="verify"><input v-model="code" class="min-w-0 flex-1 rounded-xl border p-3 dark:bg-slate-900" placeholder="Mã chứng chỉ hoặc mã xác minh"><BaseButton type="submit">Xác minh</BaseButton></form><p v-if="error" class="rounded-xl bg-red-50 p-4 text-red-700">{{ error }}</p><div v-if="certificate" class="rounded-3xl border-2 border-emerald-200 bg-white p-8 text-center dark:bg-slate-900"><div class="text-6xl">{{ certificate.revokedAt?'❌':'✅' }}</div><h2 class="mt-4 text-2xl font-extrabold">{{ certificate.revokedAt?'Chứng chỉ đã bị thu hồi':'Chứng chỉ hợp lệ' }}</h2><p class="mt-5 text-xl font-bold">{{ certificate.courseTitleSnapshot }}</p><p>Cấp cho {{ certificate.studentNameSnapshot }}</p><p class="text-sm text-slate-500">{{ certificate.certificateNumber }}</p></div></main></DefaultLayout></template>
